import{z as l,x as o,o as B,c as p,q as r,j as i,D as a,d as e,s as n,S as s,b as A}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"资产定价深化的收束","description":"","frontmatter":{"title":"资产定价深化的收束","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/apt-map.md","filePath":"econ/apt-map.md","lastUpdated":1791063341000}'),F={name:"econ/apt-map.md"};function d(C,E,c,m,D,h){const t=o("Mermaid");return B(),p("div",null,[E[2]||(E[2]=r('<h1 id="资产定价深化的收束" tabindex="-1">资产定价深化的收束 <a class="header-anchor" href="#资产定价深化的收束" aria-label="Permalink to &quot;资产定价深化的收束&quot;">​</a></h1><div class="epigraph"><p>八课只有一个对象：核在哪里弯曲、弯多少、谁来检验——其余都是这句话的变奏。</p><footer>—— 据 Cochrane, *Asset Pricing*, 2005；Campbell and Viceira, *Strategic Asset Allocation*, 2002 整理</footer></div><p><a href="/econ/apt-empirical-challenges">上一课</a>把检验协议钉成流水线：GRS 与 Fama–MacBeth 排线、GMM 与 HJ 距离量距、t 门槛抬到 3.0、发表后看衰减。本课是「资产定价理论深化」的最后一课，本课程到此收束：把八课收成一张账——每课都是随机贴现因子的一处可观测缺陷与一种修复，以及修复后必须过的那道闸门。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>深化之后留下的不是八块知识，而是一个隐患：理论的花色太多，同一个异常能被尾部、行为、中介各自解释一遍。收束的缺口是纪律：给「读一篇新定价论文」一套可复用的检查单，让新模型落在哪一课的框架里、欠哪一课的证据，一望而知；做不到这一点的理论繁荣，只是把识别问题从黑板搬进了期刊。</p><p><span class="marginnote">第二课的 HJ 界与第七课的发表衰减是全课程的两道闸门：前者问「隐含的核可行吗」，后者问「溢价还能活多久」。任何新模型先报这两行，再谈机制——顺序颠倒过来，评审就成了投稿人的独白。</span></p><p><span class="marginnote">「随机贴现因子（SDF）」又叫「定价核」，可以翻译成一把随状态变动的折现尺：好年景，未来一元只按八折计；坏年景，未来一元反而比今天的一元更值钱。全课程说的「弯曲」，指的都是这把尺在哪些年份、被什么力量改变了刻度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一张账，按课记。第一课把核写成过程，定价一行协方差，机会集时变时多出对冲项。第二课立界：\\(\\sigma(m)/E(m)\\) 不许越过可实现的最大夏普，完备给唯一核、不完备只给区间。第三课换边际者：分歧加卖空约束下，价格由乐观尾部写，再售期权是溢价的另一个名字。第四课记楔子：交易摩擦分水平补偿与四贝塔的流动性风险两笔账，资金约束让它们时变。第五课弯在尾部：小概率大跌幅状态承担溢价，期权隐含分布是观测器。第六课把弯曲者搬进主体：习惯、损失厌恶、过度自信与套利边界，各欠各的证据。第七课设闸门：联合假设、多重检验、发表衰减。</p>',9)),(B(),i(s,null,{default:a(()=>[n(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CORE%5B%22%E6%A0%B8%20m%20%E5%9C%A8%E5%93%AA%E9%87%8C%E5%BC%AF%E6%9B%B2%22%5D%20--%3E%20CONT%5B%22%E8%BF%9E%E7%BB%AD%E6%97%B6%E9%97%B4%3A%20%E8%BF%87%E7%A8%8B%E4%B8%8E%E5%8D%8F%E6%96%B9%E5%B7%AE%22%5D%0A%20%20CORE%20--%3E%20HETE%5B%22%E5%BC%82%E8%B4%A8%E4%BF%A1%E5%BF%B5%3A%20%E8%BE%B9%E9%99%85%E4%B9%B0%E8%80%85%E4%B8%8E%E5%86%8D%E5%94%AE%E6%9C%9F%E6%9D%83%22%5D%0A%20%20CORE%20--%3E%20LIQ%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%3A%20%E6%A5%94%E5%AD%90%E4%B8%8E%E5%9B%9B%E8%B4%9D%E5%A1%94%22%5D%0A%20%20CORE%20--%3E%20TAIL%5B%22%E5%B0%BE%E9%83%A8%3A%20%E5%B7%A6%E5%B0%BE%E7%8A%B6%E6%80%81%E7%9A%84%E5%BC%AF%E6%9B%B2%22%5D%0A%20%20CORE%20--%3E%20BEH%5B%22%E8%A1%8C%E4%B8%BA%3A%20%E5%81%8F%E5%A5%BD%E4%B8%8E%E4%BF%A1%E5%BF%B5%E7%9A%84%E5%BC%AF%E6%9B%B2%22%5D%0A%20%20CONT%20--%3E%20GATE%5B%22%E4%B8%A4%E9%81%93%E9%97%B8%E9%97%A8%3A%20HJ%20%E5%8F%AF%E8%A1%8C%E6%80%A7%20%2B%20%E5%8F%91%E8%A1%A8%E5%90%8E%E5%AD%98%E6%B4%BB%22%5D%0A%20%20HETE%20--%3E%20GATE%0A%20%20LIQ%20--%3E%20GATE%0A%20%20TAIL%20--%3E%20GATE%0A%20%20BEH%20--%3E%20GATE%0A%20%20GATE%20--%3E%20LIVE%5B%22%E5%AD%98%E6%B4%BB%E6%B8%85%E5%8D%95%3A%20%E6%8A%98%E7%8E%B0%E7%8E%87%E7%9A%84%E6%97%B6%E5%8F%98%E7%BB%93%E6%9E%84%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[e("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"检查单四问，读完新模型依次问。一，核在哪些状态弯曲——外生状态、主体偏好、信念，还是中介的资产负债表；二，弯曲的可观测对应物是什么——消费、期权隐含分布、调查预期、中介杠杆，答不出对应物的弯曲无法检验；三，与哪个谜题对表——溢价、无风险利率、过度波动、换手，谜题清单即第二课的界加第七课的异象账；四，多重检验与发表衰减之后还剩多少。四问答不全的模型，多半只是给已知异象换了一层皮肤。机制层的统一判词是第七课的记账法：异象不是待消灭的谜，而是折现率时变结构的清单——本课程前六课是给这份清单配机制，机制候选越少越好，不是越多越好。",-1)),E[5]||(E[5]=A("p",null,"第一张图是全课程的地图；这一张把四问检查单画成流程——地图告诉你课与课的关系，流程告诉你拿到新模型时按什么顺序过筛。",-1)),(B(),i(s,null,{default:a(()=>[n(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEW%5B%22%E6%8B%BF%E5%88%B0%E4%B8%80%E7%AF%87%E6%96%B0%E5%AE%9A%E4%BB%B7%E8%AE%BA%E6%96%87%22%5D%20--%3E%20Q1%7B%22%E4%B8%80%E9%97%AE%EF%BC%9A%E6%A0%B8%E5%9C%A8%E5%93%AA%E4%BA%9B%E7%8A%B6%E6%80%81%E5%BC%AF%E6%9B%B2%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%22%E5%A4%96%E7%94%9F%E7%8A%B6%E6%80%81%20%2F%20%E5%81%8F%E5%A5%BD%20%2F%20%E4%BF%A1%E5%BF%B5%20%2F%20%E4%B8%AD%E4%BB%8B%E8%B4%9F%E5%80%BA%E8%A1%A8%22%7C%20Q2%7B%22%E4%BA%8C%E9%97%AE%EF%BC%9A%E5%BC%AF%E6%9B%B2%E7%9A%84%E5%8F%AF%E8%A7%82%E6%B5%8B%E5%AF%B9%E5%BA%94%E7%89%A9%E6%98%AF%E4%BB%80%E4%B9%88%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%B6%88%E8%B4%B9%20%2F%20%E6%9C%9F%E6%9D%83%E5%88%86%E5%B8%83%20%2F%20%E8%B0%83%E6%9F%A5%20%2F%20%E6%9D%A0%E6%9D%86%22%7C%20Q3%7B%22%E4%B8%89%E9%97%AE%EF%BC%9A%E4%B8%8E%E5%93%AA%E4%B8%AA%E8%B0%9C%E9%A2%98%E5%AF%B9%E8%A1%A8%EF%BC%9F%22%7D%0A%20%20Q3%20--%3E%7C%22%E6%BA%A2%E4%BB%B7%20%2F%20%E5%88%A9%E7%8E%87%20%2F%20%E6%B3%A2%E5%8A%A8%20%2F%20%E6%8D%A2%E6%89%8B%22%7C%20Q4%7B%22%E5%9B%9B%E9%97%AE%EF%BC%9A%E8%A1%B0%E5%87%8F%E6%A0%A1%E6%AD%A3%E4%B9%8B%E5%90%8E%E8%BF%98%E5%89%A9%E5%A4%9A%E5%B0%91%EF%BC%9F%22%7D%0A%20%20Q4%20--%3E%7C%22%E5%9B%9B%E9%97%AE%E5%85%A8%E7%AD%94%22%7C%20KEEP%5B%22%E7%95%99%E5%9C%A8%E6%9C%BA%E5%88%B6%E5%80%99%E9%80%89%E6%B8%85%E5%8D%95%E4%B8%8A%22%5D%0A%20%20Q4%20--%3E%7C%22%E7%AD%94%E4%B8%8D%E5%85%A8%22%7C%20SKIN%5B%22%E5%A4%9A%E5%8D%8A%E6%98%AF%E6%8D%A2%E7%9A%AE%E8%82%A4%E7%9A%84%E6%97%A7%E5%BC%82%E8%B1%A1%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">为什么重要：没有检查单，每篇新论文都能自说自话地「解释」一个异象；有了四问，机制候选越少越好——识别出一个来源，比罗列五个平行故事更有信息量。理论繁荣若过不了这四问，只是把识别问题从黑板搬进了期刊。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>收束不是完成。识别问题未解：弯曲的来源常常不可分，灾难与诊断性预期、习惯与长期风险在可预测性上同预言。接口未合拢：与微观结构的接缝在<a href="/econ/microstructure-asset-pricing-interface">微观结构与资产定价的接口</a>，生产侧与需求侧的载体替换在<a href="/econ/production-based-asset-pricing">生产基础的资产定价</a>与<a href="/econ/demand-system-asset-pricing">需求系统资产定价</a>，中介与资金约束的深化在<a href="/econ/intermediary-asset-pricing">中介资产定价</a>。落地未展开：时变机会集下长期投资者的配置问题是 Campbell–Viceira 2002 的地界，本课程停在定价侧。预测与结构解释的分工，沿用上一课程立下的双轨规范：预测轨报样本外与经济价值，结构轨报识别假设与矩条件，两轨不得互借功劳。</p><p><span class="marginnote">直觉类比：这套收束像一份体检流程——八课是不同科室，两道闸门是两项硬指标（核可不可行、溢价活不活得久），四问是主诉问诊。读新模型先看化验单，再听医生讲机制故事；顺序反了，故事再动听也不该开药。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>八课一以贯之：核的弯曲位置、幅度、可观测对应物与检验闸门。</li><li>两道闸门收束全课程：Hansen–Jagannathan 可行性，发表后的溢价存活率。</li><li>读新模型四问：弯在哪、观测器是什么、对哪个谜题、衰减后剩多少。</li><li>未清账目在识别、接口与配置三处；本课程到此收束，清单留给下一门课接手。</li><li>出处：Cochrane, <em>Asset Pricing</em>, 2005；Campbell and Viceira, <em>Strategic Asset Allocation</em>, 2002；据本课程八课综合整理。</li></ul>',6))])}const u=l(F,[["render",d]]);export{T as __pageData,u as default};
